from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = {(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    comps = []
    while pts:
        seed = pts.pop()
        comp = {seed}
        q = [seed]
        while q:
            r,c = q.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    z=(r+dr,c+dc)
                    if z in pts:
                        pts.remove(z); comp.add(z); q.append(z)
        comps.append(comp)
    obj = max(comps, key=len)
    r0=min(r for r,c in obj); r1=max(r for r,c in obj)
    c0=min(c for r,c in obj); c1=max(c for r,c in obj)
    shape={(r-r0,c-c0):grid[r][c] for r,c in obj}
    cr=(r0+r1)//2; cc=(c0+c1)//2
    out=[row[:] for row in grid]
    for comp in comps:
        if comp is obj or len(comp) != 1:
            continue
        ar,ac=next(iter(comp))
        top=ar-cr; left=ac-cc
        for (dr,dc),v in shape.items():
            rr,co=top+dr,left+dc
            if 0 <= rr < h and 0 <= co < w:
                out[rr][co]=v
    return out

